package android.content;public class Intent{public static final int FLAG_ACTIVITY_NEW_TASK=1,FLAG_ACTIVITY_REORDER_TO_FRONT=2;public final Class<?> target;public final java.util.Map<String,Object> extras=new java.util.LinkedHashMap<>();public Intent(Context c,Class<?> target){this.target=target;}public Intent addFlags(int flags){return this;}public Intent putExtra(String key,String value){extras.put(key,value);return this;}public Intent putExtra(String key,boolean value){extras.put(key,value);return this;}}
